// Two variable definitions
const vol = [25.0, 30.0, 35.0, 40.0, 45.0, 50.0, 55.0, 60.0, 65.0, 70.0, 75.0];
const v = OLI.random(0,10,0);
const volwa = vol[v];
const ka = 1.4e-4;
const volwasf = volwa .toPrecision(3);

const conc = [0.2, 0.25, 0.3, 0.35, 0.4, 0.45, 0.5, 0.55, 0.6, 0.65, 0.7, 0.75, 0.8];
const c1 = OLI.random(0,12,0);
const c2 = OLI.random(0,12,0);
const concwa = conc[c1] .toPrecision(3);
const concsb = conc[c2] .toPrecision(3);

const voleqpt = concwa*volwa/concsb;
const voleqptsf = voleqpt  .toPrecision(3);

const mult1 = [0.20, 0.25, 0.30, 0.35, 0.40, 0.45, 0.55, 0.60, 0.70, 0.75, 0.80];
const m1 = OLI.random(0,10,0);
const factor1 = mult1[m1];
const volsb1 = factor1*volwa;
const volsb1sf = volsb1 .toPrecision(3);


//pH before equivalence point (buffer region)
const molwa = concwa*volwa/1000;
const molsb1 = concsb*volsb1/1000;
const molwasf = molwa .toPrecision(3);
const molsb1sf = molsb1 .toPrecision(3);
const molwa1 = molwa-molsb1;
const molwa1sf = molwa1 .toPrecision(3);
const pka = -Math.log10(ka);
const ph1 = pka + Math.log10(molsb1/molwa1);
const ph1sf = ph1 .toPrecision(3);
const ph1low = 0.99*ph1
const ph1high = 1.10*ph1


//pH at equivalence point
const totvol2 = volwa + voleqpt;
const totvol2sf = totvol2 .toPrecision(3);
const conccb2 = molwa/(totvol2/1000);
const conccb2sf = conccb2 .toPrecision(3);
const kb = 1e-14/ka;
const kbsf = kb .toPrecision(2);

var x = 0;
for (let step = 0; step < 10; step++) {
  x = Math.sqrt(kb*(conccb2 - x));
}

const xsf = x .toPrecision(2);
const poh2 = -Math.log10(x);
const poh2sf = poh2 .toPrecision(3);
const ph2 = 14-poh2;
const ph2sf = ph2 .toPrecision(3);
const ph2low = 0.99*ph2;
const ph2high = 1.01*ph2;


//pH after equivalence point
const vol3 = OLI.random(1.2*voleqpt,1.5*voleqpt,1);
const vol3sf = vol3 .toPrecision(3);
const totvol3 = volwa + vol3;
const totvol3sf = totvol3 .toPrecision(3);
const conccb3 = molwa/(totvol3/1000);
const conccb3sf = conccb3 .toPrecision(3);
const molxssb = vol3*concsb/1000 - molwa;
const molxssbsf = molxssb .toPrecision(3);
const concsb3 = molxssb*1000/(volwa + vol3);
const concsb3sf = concsb3 .toPrecision(3);
const poh3 = -Math.log10(concsb3);
const poh3sf = poh3 .toPrecision(3);
const ph3 = 14-poh3;
const ph3sf = ph3 .toPrecision(4);
const ph3low = 0.99*ph3;
const ph3high = 1.01*ph3;


// Expose variables to OLI
module.exports = {
  volwa, ka, volwasf, concwa, concsb, voleqpt, voleqptsf, m1, factor1, volsb1, volsb1sf, molwa, molsb1, molwasf, molsb1sf, molwa1, molwa1sf, pka, ph1, ph1sf, ph1low, ph1high, totvol2, totvol2sf, conccb2, conccb2sf, kbsf, x, xsf, poh2, poh2sf, ph2, ph2sf, ph2low, ph2high, vol3, vol3sf, totvol3, totvol3sf, conccb3, conccb3sf, molxssb, molxssbsf, concsb3, concsb3sf, poh3, poh3sf, ph3, ph3sf, ph3low, ph3high
};
